mapper.select:
select

from corgi_evaluation e where evaluator_id = #{userId}
and e.status != 'deleted'
order by e.id desc limit #{start}, #{size}

mapper.update:
update corgi_evaluation
set status = 'deleted'
where id = #{id}
  and evaluator_id = #{userId}

mapper.select:
select

from corgi_evaluation e where apply_id = #{applyId}
and status != 'deleted'

    and evaluator_id = #{evaluatorId}
